ST.xhtml:
// ============================================================
// IMPLEMENTACAO: FB_Heartbeat
// ============================================================

IF NOT i_bEnable THEN
    t_Heartbeat(IN := FALSE);
    r_bHeartbeatOld := i_bHeartbeat;
    o_bCommunicationOK := TRUE;
    o_bFault := FALSE;
ELSE
    IF i_bHeartbeat <> r_bHeartbeatOld THEN
        r_bHeartbeatOld := i_bHeartbeat;
        t_Heartbeat(IN := FALSE);
    ELSE
        t_Heartbeat(IN := TRUE, PT := i_tTimeout);
    END_IF;

    IF t_Heartbeat.Q THEN
        o_bCommunicationOK := FALSE;
        o_bFault := TRUE;
    ELSE
        o_bCommunicationOK := TRUE;
        o_bFault := FALSE;
    END_IF;
END_IF;

// ============================================================
// IMPLEMENTACAO: FB_AxisManager
// ============================================================

o_bX_HomeCmd := FALSE;
o_bY_HomeCmd := FALSE;
o_bZ_HomeCmd := FALSE;
o_bT_HomeCmd := FALSE;

o_bX_MoveCmd := FALSE;
o_bY_MoveCmd := FALSE;
o_bZ_MoveCmd := FALSE;
o_bT_MoveCmd := FALSE;

o_rX_Target := i_rX_Target;
o_rY_Target := i_rY_Target;
o_rZ_Target := i_rZ_Target;
o_rT_Target := i_rT_Target;

o_bFault := FALSE;

IF NOT i_bEnable THEN
    i_State := 0;
    o_bHomingComplete := FALSE;
    o_bAxesReady := FALSE;
ELSE

    CASE i_State OF

        0:
            o_bHomingComplete := FALSE;
            o_bAxesReady := FALSE;

            IF i_bHomeRequest THEN
                i_State := 10;
            END_IF;

        10:
            o_bX_HomeCmd := TRUE;

            IF i_bX_Homed THEN
                i_State := 20;
            END_IF;

        20:
            o_bY_HomeCmd := TRUE;

            IF i_bY_Homed THEN
                i_State := 30;
            END_IF;

        30:
            o_bZ_HomeCmd := TRUE;

            IF i_bZ_Homed THEN
                i_State := 40;
            END_IF;

        40:
            o_bT_HomeCmd := TRUE;

            IF i_bT_Homed THEN
                i_State := 50;
            END_IF;

        50:
            o_bHomingComplete := TRUE;
            o_bAxesReady := TRUE;

        ELSE
            i_State := 0;

    END_CASE;

    IF i_bX_Error OR
       i_bY_Error OR
       i_bZ_Error OR
       i_bT_Error THEN

        o_bFault := TRUE;
        o_bAxesReady := FALSE;
    END_IF;

END_IF;

// ============================================================
// IMPLEMENTACAO: FB_Conveyor
// ============================================================

o_bZone1Motor := FALSE;
o_bZone2Motor := FALSE;
o_bZone3Motor := FALSE;

o_bSMEMA_InReady := FALSE;
o_bSMEMA_OutAvailable := FALSE;
o_bFault := FALSE;

o_bBoardAtAssembly := i_bZone2Present;
o_bBoardAtAOI := i_bZone3Present;

IF NOT i_bEnable OR i_bStop THEN

    i_State := 0;
    t_Transfer(IN := FALSE);

ELSE

    CASE i_State OF

        0:
            o_bSMEMA_InReady := TRUE;

            IF i_bStart AND
               i_bSMEMA_InAvailable AND
               NOT i_bZone1Present THEN

                i_State := 10;
            END_IF;

        10:
            o_bZone1Motor := TRUE;

            IF i_bZone2Present THEN
                o_bZone1Motor := FALSE;
                i_State := 20;
            END_IF;

        20:
            IF NOT i_bZone2Present THEN
                i_State := 30;
            END_IF;

        30:
            IF i_bZone3Present THEN
                i_State := 40;
            ELSE
                o_bZone2Motor := TRUE;

                IF i_bZone3Present THEN
                    o_bZone2Motor := FALSE;
                    i_State := 40;
                END_IF;
            END_IF;

        40:
            o_bSMEMA_OutAvailable := TRUE;

            IF i_bSMEMA_OutReady THEN
                o_bZone3Motor := TRUE;
                i_State := 50;
            END_IF;

        50:
            o_bZone3Motor := TRUE;

            IF NOT i_bZone3Present THEN
                o_bZone3Motor := FALSE;
                i_State := 0;
            END_IF;

        ELSE
            i_State := 0;

    END_CASE;

END_IF;

// ============================================================
// IMPLEMENTACAO: FB_PneumaticActuator
// ============================================================

o_bExtendOutput := FALSE;
o_bRetractOutput := FALSE;
o_bExtended := FALSE;
o_bRetracted := FALSE;
o_bFault := FALSE;

t_Extend(IN := FALSE);
t_Retract(IN := FALSE);

IF NOT i_bEnable THEN
    RETURN;
END_IF;

o_bExtended := i_bExtendedSensor;
o_bRetracted := i_bRetractedSensor;

IF i_bExtendCmd AND NOT i_bRetractCmd THEN

    o_bExtendOutput := TRUE;

    t_Extend(
        IN := NOT i_bExtendedSensor,
        PT := i_tMaxMovement
    );

    IF t_Extend.Q THEN
        o_bFault := TRUE;
    END_IF;

ELSIF i_bRetractCmd AND NOT i_bExtendCmd THEN

    o_bRetractOutput := TRUE;

    t_Retract(
        IN := NOT i_bRetractedSensor,
        PT := i_tMaxMovement
    );

    IF t_Retract.Q THEN
        o_bFault := TRUE;
    END_IF;

END_IF;

IF i_bExtendedSensor AND i_bRetractedSensor THEN
    o_bFault := TRUE;
END_IF;

// ============================================================
// IMPLEMENTACAO: FB_PickPlace
// ============================================================

o_bX_Move := FALSE;
o_bY_Move := FALSE;
o_bZ_Move := FALSE;
o_bT_Move := FALSE;

o_bVacuum := FALSE;
o_bNozzleDown := FALSE;
o_bNozzleUp := FALSE;
o_bRelease := FALSE;

o_bComplete := FALSE;
o_bBusy := FALSE;
o_bFault := FALSE;

t_Vacuum(IN := FALSE);

IF NOT i_bEnable OR i_bStop THEN
    i_State := 0;
    o_iComponentIndex := 1;
    RETURN;
END_IF;

CASE i_State OF

    0:
        o_iComponentIndex := 1;

        IF i_bStart AND
           i_bAxesReady AND
           i_bComponentAvailable THEN

            o_bBusy := TRUE;
            i_State := 10;
        END_IF;

    10:
        // ----------------------------------------------------
        // POSICAO DE COLETA
        // ----------------------------------------------------
        o_bX_Move := TRUE;
        o_bY_Move := TRUE;
        o_bT_Move := TRUE;

        o_rX_Target := i_rPickX;
        o_rY_Target := i_rPickY;
        o_rT_Target := i_rPickT;

        IF i_bX_InPosition AND
           i_bY_InPosition AND
           i_bT_InPosition THEN

            i_State := 20;
        END_IF;

    20:
        // ----------------------------------------------------
        // DESCIDA DO BICO
        // ----------------------------------------------------
        o_bNozzleDown := TRUE;
        o_rZ_Target := i_rPickZ;

        IF i_bZ_InPosition AND i_bNozzleDown THEN
            i_State := 30;
        END_IF;

    30:
        // ----------------------------------------------------
        // APLICACAO DO VACUO
        // ----------------------------------------------------
        o_bVacuum := TRUE;

        t_Vacuum(
            IN := NOT i_bVacuumOK,
            PT := T#1s
        );

        IF i_bVacuumOK THEN
            i_State := 40;
        ELSIF t_Vacuum.Q THEN
            o_bFault := TRUE;
            i_State := 900;
        END_IF;

    40:
        // ----------------------------------------------------
        // SUBIDA DO BICO
        // ----------------------------------------------------
        o_bVacuum := TRUE;
        o_bNozzleUp := TRUE;

        IF i_bZ_InPosition AND i_bNozzleUp THEN
            i_State := 50;
        END_IF;

    50:
        // ----------------------------------------------------
        // POSICAO DE DEPOSITO
        // ----------------------------------------------------
        o_bVacuum := TRUE;

        o_bX_Move := TRUE;
        o_bY_Move := TRUE;
        o_bT_Move := TRUE;

        o_rX_Target := i_rPlaceX;
        o_rY_Target := i_rPlaceY;
        o_rT_Target := i_rPlaceT;

        IF i_bX_InPosition AND
           i_bY_InPosition AND
           i_bT_InPosition THEN

            i_State := 60;
        END_IF;

    60:
        // ----------------------------------------------------
        // DESCIDA PARA DEPOSITO
        // ----------------------------------------------------
        o_bVacuum := TRUE;
        o_bNozzleDown := TRUE;
        o_rZ_Target := i_rPlaceZ;

        IF i_bZ_InPosition AND i_bNozzleDown THEN
            i_State := 70;
        END_IF;

    70:
        // ----------------------------------------------------
        // LIBERACAO DO COMPONENTE
        // ----------------------------------------------------
        o_bVacuum := FALSE;
        o_bRelease := TRUE;

        i_State := 80;

    80:
        // ----------------------------------------------------
        // RETORNO DO BICO
        // ----------------------------------------------------
        o_bNozzleUp := TRUE;

        IF i_bZ_InPosition AND i_bNozzleUp THEN

            IF o_iComponentIndex < i_iComponentQty THEN
                o_iComponentIndex := o_iComponentIndex + 1;
                i_State := 10;
            ELSE
                i_State := 100;
            END_IF;

        END_IF;

    100:
        o_bBusy := FALSE;
        o_bComplete := TRUE;
        i_State := 0;

    900:
        o_bBusy := FALSE;
        o_bFault := TRUE;

    ELSE
        i_State := 0;

END_CASE;

// ============================================================
// IMPLEMENTACAO: FB_AOI
// ============================================================

o_bTrigger := FALSE;
o_bBusy := FALSE;
o_bComplete := FALSE;
o_bRejected := FALSE;
o_bFault := FALSE;

t_Inspection(IN := FALSE);

IF NOT i_bEnable THEN
    i_State := 0;
    o_iAttempt := 0;
    RETURN;
END_IF;

CASE i_State OF

    0:
        o_iAttempt := 0;

        IF i_bStart AND
           i_bBoardPresent AND
           i_bAOIReady THEN

            o_iAttempt := 1;
            o_bBusy := TRUE;
            i_State := 10;
        END_IF;

    10:
        o_bBusy := TRUE;
        o_bTrigger := TRUE;

        i_State := 20;

    20:
        o_bBusy := TRUE;

        t_Inspection(
            IN := i_bAOIBusy,
            PT := T#5s
        );

        IF i_bResultOK THEN
            i_State := 100;

        ELSIF i_bResultNOK THEN

            IF o_iAttempt < 3 THEN
                o_iAttempt := o_iAttempt + 1;
                i_State := 10;
            ELSE
                i_State := 200;
            END_IF;

        ELSIF t_Inspection.Q THEN
            o_bFault := TRUE;
            i_State := 900;
        END_IF;

    100:
        o_bBusy := FALSE;
        o_bComplete := TRUE;
        o_bRejected := FALSE;
        i_State := 0;

    200:
        o_bBusy := FALSE;
        o_bComplete := TRUE;
        o_bRejected := TRUE;
        i_State := 0;

    900:
        o_bBusy := FALSE;
        o_bFault := TRUE;

    ELSE
        i_State := 0;

END_CASE;

// ============================================================
// IMPLEMENTACAO: FB_AlarmManager
// ============================================================

o_bEmergencyAlarm := NOT i_bEmergencyOK;
o_bGuardAlarm := NOT i_bGuardOK;
o_bHMIAlarm := NOT i_bHMI_OK;

o_bAxisAlarm := i_bAxisFault;
o_bPneumaticAlarm := i_bPneumaticFault;
o_bVacuumAlarm := i_bVacuumFault;
o_bAOIAlarm := i_bAOIFault;
o_bSMEMAAlarm := i_bSMEMAFault;

o_iAlarmCode := 0;

IF o_bEmergencyAlarm THEN
    o_iAlarmCode := 1;
ELSIF o_bGuardAlarm THEN
    o_iAlarmCode := 2;
ELSIF o_bHMIAlarm THEN
    o_iAlarmCode := 3;
ELSIF o_bAxisAlarm THEN
    o_iAlarmCode := 4;
ELSIF o_bPneumaticAlarm THEN
    o_iAlarmCode := 5;
ELSIF o_bVacuumAlarm THEN
    o_iAlarmCode := 6;
ELSIF o_bAOIAlarm THEN
    o_iAlarmCode := 7;
ELSIF o_bSMEMAAlarm THEN
    o_iAlarmCode := 8;
END_IF;

o_bAlarmActive :=
    o_bEmergencyAlarm OR
    o_bGuardAlarm OR
    o_bHMIAlarm OR
    o_bAxisAlarm OR
    o_bPneumaticAlarm OR
    o_bVacuumAlarm OR
    o_bAOIAlarm OR
    o_bSMEMAAlarm;

IF i_bReset AND
   i_bEmergencyOK AND
   i_bGuardOK AND
   i_bHMI_OK THEN

    IF NOT i_bAxisFault AND
       NOT i_bPneumaticFault AND
       NOT i_bVacuumFault AND
       NOT i_bAOIFault AND
       NOT i_bSMEMAFault THEN

        o_bAlarmActive := FALSE;
        o_iAlarmCode := 0;
    END_IF;
END_IF;

// ============================================================
// IMPLEMENTACAO: FB_RecipeManager
// ============================================================

o_bValid := FALSE;

IF i_bMachineStopped THEN

    CASE i_iSelectedRecipe OF

        1:
            o_iActiveRecipe := 1;
            o_iComponentQty := g_iRecipe1_ComponentQty;

            o_rX[1] := g_rRecipe1_X[1];
            o_rX[2] := g_rRecipe1_X[2];
            o_rX[3] := g_rRecipe1_X[3];
            o_rX[4] := g_rRecipe1_X[4];
            o_rX[5] := g_rRecipe1_X[5];
            o_rX[6] := g_rRecipe1_X[6];
            o_rX[7] := g_rRecipe1_X[7];
            o_rX[8] := g_rRecipe1_X[8];
            o_rX[9] := g_rRecipe1_X[9];
            o_rX[10] := g_rRecipe1_X[10];

            o_rY[1] := g_rRecipe1_Y[1];
            o_rY[2] := g_rRecipe1_Y[2];
            o_rY[3] := g_rRecipe1_Y[3];
            o_rY[4] := g_rRecipe1_Y[4];
            o_rY[5] := g_rRecipe1_Y[5];
            o_rY[6] := g_rRecipe1_Y[6];
            o_rY[7] := g_rRecipe1_Y[7];
            o_rY[8] := g_rRecipe1_Y[8];
            o_rY[9] := g_rRecipe1_Y[9];
            o_rY[10] := g_rRecipe1_Y[10];

            o_rT[1] := g_rRecipe1_T[1];
            o_rT[2] := g_rRecipe1_T[2];
            o_rT[3] := g_rRecipe1_T[3];
            o_rT[4] := g_rRecipe1_T[4];
            o_rT[5] := g_rRecipe1_T[5];
            o_rT[6] := g_rRecipe1_T[6];
            o_rT[7] := g_rRecipe1_T[7];
            o_rT[8] := g_rRecipe1_T[8];
            o_rT[9] := g_rRecipe1_T[9];
            o_rT[10] := g_rRecipe1_T[10];

            o_bValid := TRUE;

        2:
            o_iActiveRecipe := 2;
            o_iComponentQty := g_iRecipe2_ComponentQty;

            o_rX[1] := g_rRecipe2_X[1];
            o_rX[2] := g_rRecipe2_X[2];
            o_rX[3] := g_rRecipe2_X[3];
            o_rX[4] := g_rRecipe2_X[4];
            o_rX[5] := g_rRecipe2_X[5];
            o_rX[6] := g_rRecipe2_X[6];
            o_rX[7] := g_rRecipe2_X[7];
            o_rX[8] := g_rRecipe2_X[8];
            o_rX[9] := g_rRecipe2_X[9];
            o_rX[10] := g_rRecipe2_X[10];

            o_rY[1] := g_rRecipe2_Y[1];
            o_rY[2] := g_rRecipe2_Y[2];
            o_rY[3] := g_rRecipe2_Y[3];
            o_rY[4] := g_rRecipe2_Y[4];
            o_rY[5] := g_rRecipe2_Y[5];
            o_rY[6] := g_rRecipe2_Y[6];
            o_rY[7] := g_rRecipe2_Y[7];
            o_rY[8] := g_rRecipe2_Y[8];
            o_rY[9] := g_rRecipe2_Y[9];
            o_rY[10] := g_rRecipe2_Y[10];

            o_rT[1] := g_rRecipe2_T[1];
            o_rT[2] := g_rRecipe2_T[2];
            o_rT[3] := g_rRecipe2_T[3];
            o_rT[4] := g_rRecipe2_T[4];
            o_rT[5] := g_rRecipe2_T[5];
            o_rT[6] := g_rRecipe2_T[6];
            o_rT[7] := g_rRecipe2_T[7];
            o_rT[8] := g_rRecipe2_T[8];
            o_rT[9] := g_rRecipe2_T[9];
            o_rT[10] := g_rRecipe2_T[10];

            o_bValid := TRUE;

        3:
            o_iActiveRecipe := 3;
            o_iComponentQty := g_iRecipe3_ComponentQty;

            o_rX[1] := g_rRecipe3_X[1];
            o_rX[2] := g_rRecipe3_X[2];
            o_rX[3] := g_rRecipe3_X[3];
            o_rX[4] := g_rRecipe3_X[4];
            o_rX[5] := g_rRecipe3_X[5];
            o_rX[6] := g_rRecipe3_X[6];
            o_rX[7] := g_rRecipe3_X[7];
            o_rX[8] := g_rRecipe3_X[8];
            o_rX[9] := g_rRecipe3_X[9];
            o_rX[10] := g_rRecipe3_X[10];

            o_rY[1] := g_rRecipe3_Y[1];
            o_rY[2] := g_rRecipe3_Y[2];
            o_rY[3] := g_rRecipe3_Y[3];
            o_rY[4] := g_rRecipe3_Y[4];
            o_rY[5] := g_rRecipe3_Y[5];
            o_rY[6] := g_rRecipe3_Y[6];
            o_rY[7] := g_rRecipe3_Y[7];
            o_rY[8] := g_rRecipe3_Y[8];
            o_rY[9] := g_rRecipe3_Y[9];
            o_rY[10] := g_rRecipe3_Y[10];

            o_rT[1] := g_rRecipe3_T[1];
            o_rT[2] := g_rRecipe3_T[2];
            o_rT[3] := g_rRecipe3_T[3];
            o_rT[4] := g_rRecipe3_T[4];
            o_rT[5] := g_rRecipe3_T[5];
            o_rT[6] := g_rRecipe3_T[6];
            o_rT[7] := g_rRecipe3_T[7];
            o_rT[8] := g_rRecipe3_T[8];
            o_rT[9] := g_rRecipe3_T[9];
            o_rT[10] := g_rRecipe3_T[10];

            o_bValid := TRUE;

        ELSE
            o_bValid := FALSE;

    END_CASE;

END_IF;

// ============================================================
// IMPLEMENTACAO: PRG_Main
// ============================================================

// ============================================================
// SEGURANCA PRINCIPAL
// ============================================================

g_bSafetyOK :=
    g_bEmergencyOK AND
    g_bGuardDoorOK AND
    g_bHMICommunicationOK;

// ============================================================
// HEARTBEAT DA IHM
// ============================================================

fbHeartbeat(
    i_bHeartbeat := g_bHMIHeartbeat,
    i_bEnable := TRUE,
    i_tTimeout := g_tHMIHeartbeatTimeout
);

g_bHMICommunicationOK := fbHeartbeat.o_bCommunicationOK;
g_bAlarmHMI := fbHeartbeat.o_bFault;

// ============================================================
// DETECCAO DE ESTADO PARADO
// ============================================================

bMachineStopped :=
    NOT g_bMachineRunning AND
    (i_State = 0);

// ============================================================
// GERENCIAMENTO DA RECEITA
// ============================================================

fbRecipe(
    i_bMachineStopped := bMachineStopped,
    i_iSelectedRecipe := g_iSelectedRecipe
);

IF bMachineStopped AND
   fbRecipe.o_bValid THEN

    g_iActiveRecipe := fbRecipe.o_iActiveRecipe;
END_IF;

// ============================================================
// GERENCIAMENTO DOS EIXOS
// ============================================================

fbAxes(
    i_bEnable := g_bSafetyOK,
    i_bHomeRequest := g_bHomingRequest,
    i_bX_Homed := g_bAxisX_Homed,
    i_bY_Homed := g_bAxisY_Homed,
    i_bZ_Homed := g_bAxisZ_Homed,
    i_bT_Homed := g_bAxisT_Homed,
    i_bX_InPosition := g_bAxisX_InPosition,
    i_bY_InPosition := g_bAxisY_InPosition,
    i_bZ_InPosition := g_bAxisZ_InPosition,
    i_bT_InPosition := g_bAxisT_InPosition,
    i_bX_Error := g_bAxisX_Error,
    i_bY_Error := g_bAxisY_Error,
    i_bZ_Error := g_bAxisZ_Error,
    i_bT_Error := g_bAxisT_Error,
    i_rX_Target := g_rAxisX_Target,
    i_rY_Target := g_rAxisY_Target,
    i_rZ_Target := g_rAxisZ_Target,
    i_rT_Target := g_rAxisT_Target
);

g_bAxisX_HomeCmd := fbAxes.o_bX_HomeCmd;
g_bAxisY_HomeCmd := fbAxes.o_bY_HomeCmd;
g_bAxisZ_HomeCmd := fbAxes.o_bZ_HomeCmd;
g_bAxisT_HomeCmd := fbAxes.o_bT_HomeCmd;

g_bAxisX_MoveCmd := fbAxes.o_bX_MoveCmd;
g_bAxisY_MoveCmd := fbAxes.o_bY_MoveCmd;
g_bAxisZ_MoveCmd := fbAxes.o_bZ_MoveCmd;
g_bAxisT_MoveCmd := fbAxes.o_bT_MoveCmd;

g_rAxisX_Target := fbAxes.o_rX_Target;
g_rAxisY_Target := fbAxes.o_rY_Target;
g_rAxisZ_Target := fbAxes.o_rZ_Target;
g_rAxisT_Target := fbAxes.o_rT_Target;

g_bHomingComplete := fbAxes.o_bHomingComplete;

// ============================================================
// ESTEIRA
// ============================================================

fbConveyor(
    i_bEnable := g_bSafetyOK,
    i_bStart := g_bStartCycle,
    i_bStop := g_bStopCycle,
    i_bZone1Present := g_bZone1_BoardPresent,
    i_bZone2Present := g_bZone2_BoardPresent,
    i_bZone3Present := g_bZone3_BoardPresent,
    i_bSMEMA_InAvailable := g_bSMEMA_In_Available,
    i_bSMEMA_OutReady := g_bSMEMA_Out_Ready
);

g_bZone1_MotorCmd := fbConveyor.o_bZone1Motor;
g_bZone2_MotorCmd := fbConveyor.o_bZone2Motor;
g_bZone3_MotorCmd := fbConveyor.o_bZone3Motor;

g_bSMEMA_In_Ready := fbConveyor.o_bSMEMA_InReady;
g_bSMEMA_Out_Available := fbConveyor.o_bSMEMA_OutAvailable;

// ============================================================
// ATUADOR DO BICO
// ============================================================

fbNozzle(
    i_bEnable := g_bSafetyOK,
    i_bExtendCmd := g_bNozzleDownCmd,
    i_bRetractCmd := g_bNozzleUpCmd,
    i_bExtendedSensor := g_bNozzleDownSensor,
    i_bRetractedSensor := g_bNozzleUpSensor,
    i_tMaxMovement := T#2s
);

g_bAlarmPneumatic := fbNozzle.o_bFault;

// ============================================================
// ATUADOR DA FIXACAO DA PLACA
// ============================================================

fbClamp(
    i_bEnable := g_bSafetyOK,
    i_bExtendCmd := g_bClampCloseCmd,
    i_bRetractCmd := g_bClampOpenCmd,
    i_bExtendedSensor := g_bClampClosedSensor,
    i_bRetractedSensor := g_bClampOpenSensor,
    i_tMaxMovement := T#2s
);

IF fbClamp.o_bFault THEN
    g_bAlarmPneumatic := TRUE;
END_IF;

// ============================================================
// LOGICA PRINCIPAL DA CELULA
// ============================================================

IF NOT g_bSafetyOK THEN

    i_State := 0;
    g_bMachineRunning := FALSE;
    g_bBoardInProcess := FALSE;
    g_bPickVacuumCmd := FALSE;
    g_bPlaceReleaseCmd := FALSE;

ELSE

    CASE i_State OF

        // ====================================================
        // 0 - PARADA / INICIALIZACAO
        // ====================================================
        0:
            g_bMachineRunning := FALSE;
            g_bBoardInProcess := FALSE;
            g_bCycleComplete := FALSE;

            IF g_bReset THEN
                g_bMachineFault := FALSE;
            END_IF;

            IF g_bAutoMode AND
               g_bStartCycle AND
               g_bHomingComplete AND
               NOT g_bAlarmActive THEN

                g_bMachineRunning := TRUE;
                i_State := 10;
            END_IF;

        // ====================================================
        // 10 - AGUARDAR PLACA NA ENTRADA
        // ====================================================
        10:
            g_bMachineRunning := TRUE;

            IF g_bZone1_BoardPresent THEN
                i_State := 20;
            END_IF;

        // ====================================================
        // 20 - TRANSFERIR PARA ZONA DE MONTAGEM
        // ====================================================
        20:
            g_bMachineRunning := TRUE;

            IF g_bZone2_BoardPresent THEN
                g_bBoardInProcess := TRUE;
                i_State := 30;
            END_IF;

        // ====================================================
        // 30 - FIXAR PLACA
        // ====================================================
        30:
            g_bClampCloseCmd := TRUE;
            g_bClampOpenCmd := FALSE;

            IF g_bClampClosedSensor THEN
                i_State := 40;
            END_IF;

        // ====================================================
        // 40 - PICK AND PLACE
        // ====================================================
        40:

            IF fbRecipe.o_bValid AND
               fbAxes.o_bAxesReady THEN

                iComponentIndex := fbPickPlace.o_iComponentIndex;

                IF iComponentIndex < 1 THEN
                    iComponentIndex := 1;
                END_IF;

                IF iComponentIndex > 10 THEN
                    iComponentIndex := 10;
                END_IF;

                rPlaceX := fbRecipe.o_rX[iComponentIndex];
                rPlaceY := fbRecipe.o_rY[iComponentIndex];
                rPlaceT := fbRecipe.o_rT[iComponentIndex];

                fbPickPlace(
                    i_bEnable := g_bSafetyOK,
                    i_bStart := TRUE,
                    i_bStop := g_bStopCycle,
                    i_bAxesReady := fbAxes.o_bAxesReady,
                    i_bComponentAvailable := g_bComponentAvailable,
                    i_bVacuumOK := g_bPickVacuumOK,
                    i_bX_InPosition := g_bAxisX_InPosition,
                    i_bY_InPosition := g_bAxisY_InPosition,
                    i_bZ_InPosition := g_bAxisZ_InPosition,
                    i_bT_InPosition := g_bAxisT_InPosition,
                    i_bNozzleDown := g_bNozzleDownSensor,
                    i_bNozzleUp := g_bNozzleUpSensor,
                    i_iComponentQty := fbRecipe.o_iComponentQty,
                    i_rPickX := rPickX,
                    i_rPickY := rPickY,
                    i_rPickZ := rPickZ,
                    i_rPickT := rPickT,
                    i_rPlaceX := rPlaceX,
                    i_rPlaceY := rPlaceY,
                    i_rPlaceZ := rPlaceZ,
                    i_rPlaceT := rPlaceT
                );

                g_bPickVacuumCmd := fbPickPlace.o_bVacuum;
                g_bNozzleDownCmd := fbPickPlace.o_bNozzleDown;
                g_bNozzleUpCmd := fbPickPlace.o_bNozzleUp;
                g_bPlaceReleaseCmd := fbPickPlace.o_bRelease;

                IF fbPickPlace.o_bComplete THEN
                    i_State := 50;
                END_IF;

                IF fbPickPlace.o_bFault THEN
                    g_bMachineFault := TRUE;
                    i_State := 900;
                END_IF;

            END_IF;

        // ====================================================
        // 50 - LIBERAR FIXACAO
        // ====================================================
        50:
            g_bClampCloseCmd := FALSE;
            g_bClampOpenCmd := TRUE;

            IF g_bClampOpenSensor THEN
                i_State := 60;
            END_IF;

        // ====================================================
        // 60 - TRANSFERIR PARA AOI
        // ====================================================
        60:
            IF g_bZone3_BoardPresent THEN
                i_State := 70;
            END_IF;

        // ====================================================
        // 70 - INSPECAO AOI
        // ====================================================
        70:

            fbAOI(
                i_bEnable := g_bSafetyOK,
                i_bStart := TRUE,
                i_bBoardPresent := g_bZone3_BoardPresent,
                i_bAOIReady := g_bAOI_Ready,
                i_bAOIBusy := g_bAOI_Busy,
                i_bResultOK := g_bAOI_ResultOK,
                i_bResultNOK := g_bAOI_ResultNOK
            );

            g_bAOI_Trigger := fbAOI.o_bTrigger;

            IF fbAOI.o_bComplete THEN

                IF fbAOI.o_bRejected THEN
                    g_bBoardRejected := TRUE;
                    i_State := 80;
                ELSE
                    g_bBoardRejected := FALSE;
                    i_State := 80;
                END_IF;

            END_IF;

            IF fbAOI.o_bFault THEN
                g_bMachineFault := TRUE;
                i_State := 900;
            END_IF;

        // ====================================================
        // 80 - CONTAGEM E EXPEDICAO
        // ====================================================
        80:

            IF g_bBoardRejected THEN
                g_uiBoardsRejected := g_uiBoardsRejected + 1;
            ELSE
                g_uiBoardsProduced := g_uiBoardsProduced + 1;
            END_IF;

            g_bCycleComplete := TRUE;

            i_State := 90;

        // ====================================================
        // 90 - TRANSFERENCIA PARA MAQUINA VIZINHA
        // ====================================================
        90:

            IF g_bSMEMA_Out_Ready THEN
                g_bZone3_MotorCmd := TRUE;

                IF NOT g_bZone3_BoardPresent THEN
                    g_bBoardInProcess := FALSE;
                    g_bCycleComplete := FALSE;
                    g_bBoardRejected := FALSE;
                    i_State := 10;
                END_IF;
            END_IF;

        // ====================================================
        // 900 - FALHA
        // ====================================================
        900:
            g_bMachineRunning := FALSE;
            g_bMachineFault := TRUE;

            g_bZone1_MotorCmd := FALSE;
            g_bZone2_MotorCmd := FALSE;
            g_bZone3_MotorCmd := FALSE;

            g_bPickVacuumCmd := FALSE;
            g_bPlaceReleaseCmd := FALSE;

            IF g_bReset AND
               NOT g_bAlarmActive AND
               g_bSafetyOK THEN

                g_bMachineFault := FALSE;
                i_State := 0;
            END_IF;

        ELSE
            i_State := 0;

    END_CASE;

END_IF;

// ============================================================
// ALARMES
// ============================================================

bAxisFault :=
    g_bAxisX_Error OR
    g_bAxisY_Error OR
    g_bAxisZ_Error OR
    g_bAxisT_Error;

bPneumaticFault :=
    fbNozzle.o_bFault OR
    fbClamp.o_bFault;

bPickPlaceFault :=
    fbPickPlace.o_bFault;

bAOIFault :=
    fbAOI.o_bFault;

fbAlarms(
    i_bEmergencyOK := g_bEmergencyOK,
    i_bGuardOK := g_bGuardDoorOK,
    i_bHMI_OK := g_bHMICommunicationOK,
    i_bAxisFault := bAxisFault,
    i_bPneumaticFault := bPneumaticFault,
    i_bVacuumFault := bPickPlaceFault,
    i_bAOIFault := bAOIFault,
    i_bSMEMAFault := FALSE,
    i_bReset := g_bReset
);

g_bAlarmActive := fbAlarms.o_bAlarmActive;
g_bAlarmEmergency := fbAlarms.o_bEmergencyAlarm;
g_bAlarmGuard := fbAlarms.o_bGuardAlarm;
g_bAlarmHMI := fbAlarms.o_bHMIAlarm;
g_bAlarmAxis := fbAlarms.o_bAxisAlarm;
g_bAlarmPneumatic := fbAlarms.o_bPneumaticAlarm;
g_bAlarmVacuum := fbAlarms.o_bVacuumAlarm;
g_bAlarmAOI := fbAlarms.o_bAOIAlarm;
g_bAlarmSMEMA := fbAlarms.o_bSMEMAAlarm;
g_iAlarmCode := fbAlarms.o_iAlarmCode;

// ============================================================
// INTERTRAVAMENTO FINAL DE SEGURANCA
// ============================================================

IF NOT g_bEmergencyOK OR
   NOT g_bGuardDoorOK OR
   NOT g_bHMICommunicationOK THEN

    g_bZone1_MotorCmd := FALSE;
    g_bZone2_MotorCmd := FALSE;
    g_bZone3_MotorCmd := FALSE;

    g_bPickVacuumCmd := FALSE;
    g_bPlaceReleaseCmd := FALSE;

    g_bMachineRunning := FALSE;
    g_bMachineFault := TRUE;

END_IF;

g_iMachineState := i_State;
g_bMachineReady :=
    g_bSafetyOK AND
    g_bHomingComplete AND
    NOT g_bAlarmActive AND
    NOT g_bMachineFault;
